<script setup lang="ts">
import {localDateTime} from '@/domain/platform-modules'
import QualityCatalogManager from './QualityCatalogManager.vue'
import {dateError,validDate} from '@/domain/dates'
import {computed,ref} from 'vue'
import {qualityCommand} from '@/services/quality'
export interface Field {key:string;label:string;type?:string;required?:boolean;options?:{value:any;label:string}[];details?:boolean;when?:{key:string;value:any}}
const props=defineProps<{title:string;operation:string;id?:string|null;initial:Record<string,any>;fields:Field[];context?:string}>()
const emit=defineEmits(['saved','close'])
const form=ref(Object.fromEntries(Object.entries(props.initial).map(([k,v])=>[k,props.fields.some(f=>f.key===k&&['numbers','list'].includes(f.type||''))&&Array.isArray(v)?v.join(', '):v]))),busy=ref(false),error=ref(''),confirmed=ref(false)
const needsConfirmation=computed(()=>!['occurrence_create','area_save','auditor_save'].includes(props.operation))
for(const f of props.fields)if(f.type==='datetime-local'&&form.value[f.key])form.value[f.key]=localDateTime(form.value[f.key])
const manage=ref<'auditor'|'area'|null>(null)
const refreshed=ref<any>(null)
function options(f:Field){if(refreshed.value&&f.key==='auditor_id')return refreshed.value.auditors.filter((r:any)=>r.active||r.id===form.value.auditor_id).map((r:any)=>({value:r.id,label:r.name}));if(refreshed.value&&f.key==='area_ids')return refreshed.value.areas.filter((r:any)=>r.active||form.value.area_ids?.includes(r.id)).map((r:any)=>({value:r.id,label:r.name}));return f.options}
function visible(field:Field){return !field.when||form.value[field.when.key]===field.when.value}
async function save(){if(needsConfirmation.value&&!confirmed.value)return;busy.value=true;error.value='';try{const payload={...form.value};for(const f of props.fields.filter(visible)){const v=payload[f.key];if(f.required&&(v==null||v===''||Array.isArray(v)&&(!v.length||v.includes(''))))throw new Error(f.key==='area_ids'?'Selecione pelo menos uma área/processo abrangido.':`Preencha o campo ${f.label}.`);if(f.type==='date'&&v&&!validDate(v))throw new Error(dateError)}for(const f of props.fields)if(f.type==='number'&&payload[f.key]!=='')payload[f.key]=Number(payload[f.key]);for(const f of props.fields){if(f.type==='numbers')payload[f.key]=String(payload[f.key]).split(',').map(v=>Number(v.trim()));if(f.type==='list')payload[f.key]=String(payload[f.key]).split(',').map(v=>v.trim()).filter(Boolean)}if(payload.finding_type){payload.type=payload.finding_type==='OM'?'OM':'NC';payload.classification=payload.type==='NC'?payload.finding_type:null;delete payload.finding_type}for(const f of props.fields)if(f.type==='datetime-local'&&payload[f.key])payload[f.key]=new Date(payload[f.key]).toISOString();const result=await qualityCommand(props.operation,props.id||null,payload);emit('saved',result)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
 <div class="modal d-block" role="dialog" aria-modal="true" :aria-label="title" style="background:#0007"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form novalidate class="modal-content" @submit.prevent="save"><div class="modal-header"><h2 class="modal-title fs-5">{{title}}</h2><button class="btn-close" type="button" aria-label="Fechar" :disabled="busy" @click="emit('close')"></button></div><div class="modal-body">
 <p v-if="context" class="text-body-secondary">{{context}}</p><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div>
 <template v-for="advanced in [false,true].filter(a=>fields.some(f=>!!f.details===a&&visible(f)))" :key="String(advanced)"><component :is="advanced?'details':'div'"><summary v-if="advanced" class="mb-3">Mais detalhes</summary><div class="row g-3 mb-3"><template v-for="f in fields.filter(f=>!!f.details===advanced&&visible(f))" :key="f.key"><div :class="f.type==='textarea'?'col-12':'col-md-6'"><label :for="'qf-'+f.key" class="form-label">{{f.label}}{{f.required?' *':''}}</label><textarea v-if="f.type==='textarea'" :id="'qf-'+f.key" v-model="form[f.key]" class="form-control" rows="3" :required="f.required"></textarea><select v-else-if="f.options" :id="'qf-'+f.key" v-model="form[f.key]" class="form-select" :multiple="f.type==='multiple'" :required="f.required"><option v-if="f.type!=='multiple'" value="">Selecionar…</option><option v-for="o in options(f)" :key="String(o.value)" :value="o.value">{{o.label}}</option></select><input v-else-if="f.type==='checkbox'" :id="'qf-'+f.key" v-model="form[f.key]" type="checkbox" class="form-check-input d-block"/><PtDateInput v-else-if="['date','datetime-local'].includes(f.type||'')" :id="'qf-'+f.key" v-model="form[f.key]" :type="f.type" class="form-control" :required="f.required"/><input v-else :id="'qf-'+f.key" v-model="form[f.key]" :type="['numbers','list'].includes(f.type||'')?'text':f.type||'text'" class="form-control" :required="f.required"/><div v-if="operation==='audit_save'&&['auditor_id','area_ids'].includes(f.key)" class="mt-2"><small v-if="!options(f)?.length" class="d-block">Ainda não existem valores disponíveis. Abra a gestão para adicionar.</small><button type="button" class="btn btn-sm btn-outline-primary" @click="manage=f.key==='auditor_id'?'auditor':'area'">{{f.key==='auditor_id'?'Gerir Auditores':'Gerir Áreas/Processos'}}</button></div></div></template></div></component>
</template>
 </div><div class="modal-footer"><label v-if="needsConfirmation" class="me-auto"><input v-model="confirmed" type="checkbox"/> Revi os dados e confirmo esta operação.</label><button class="btn btn-outline-secondary" type="button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="btn btn-primary" type="submit" :disabled="busy||(needsConfirmation&&!confirmed)">{{busy?'A guardar…':'Guardar'}}</button></div></form></div></div>
<QualityCatalogManager v-if="manage" :kind="manage" @close="manage=null" @changed="refreshed=$event"/>
</template>
